"""Article-specific editorial source for CC-07 (Civil Code arts. 251-310)."""
from __future__ import annotations


def row(says, means, example, warning, term, definition, *, target=None, terms=None):
    return {"target": target, "o_que_diz": says, "o_que_significa": means, "exemplo_pratico": example, "atencao": warning, "palavras_dificeis": terms or [{"termo": term, "explicacao": definition}]}


ROWS = {
    "251": row("Se o devedor pratica o ato que prometeu não realizar, o credor pode exigir que ele o desfaça, às suas custas, e cobre os prejuízos culpavelmente causados.", "A tutela procura restaurar a situação anterior. Havendo urgência, o próprio credor pode desfazer ou contratar terceiro para desfazer o ato, sem esperar autorização judicial, e depois pedir ressarcimento.", "Empresa ergue estrutura contrariando obrigação de não construir; o credor exige a retirada ou, diante de risco imediato, providencia a remoção.", "A atuação direta exige urgência real. Custos, culpa, necessidade e perdas adicionais devem ser comprovados, sem abuso ou duplicidade indenizatória.", "Obrigação de não fazer", "dever jurídico de abster-se de uma conduta determinada"),
    "252": row("Na obrigação alternativa, a escolha pertence em regra ao devedor, mas o contrato pode atribuí-la a outra pessoa. A prestação escolhida deve ser cumprida integralmente.", "Não se pode impor ao credor uma mistura de partes das alternativas. Em prestações periódicas, a escolha pode renovar-se a cada período. Se vários optantes não chegarem à unanimidade, ou se terceiro designado não escolher, o juiz decide nas condições legais.", "Contrato prevê entrega de cem sacas de café ou pagamento em dinheiro; quem tiver a opção escolhe uma prestação completa.", "Antes de aplicar a regra geral, confira quem recebeu a escolha no título e se há periodicidade, pluralidade de optantes ou terceiro indicado.", "Obrigação alternativa", "obrigação que pode ser satisfeita por uma entre duas ou mais prestações previstas"),
    "253": row("Se uma das duas prestações alternativas é juridicamente impossível desde o início ou depois se torna inexequível, permanece devida a outra.", "A alternativa impossível sai da relação, e a obrigação concentra-se na prestação ainda viável. A regra trata da sobrevivência do débito, sem afirmar por si só responsabilidade por perdas e danos.", "Promessa permite entregar equipamento ou licença que depois deixa de poder ser validamente transferida; subsiste a entrega do equipamento.", "A causa da impossibilidade e a titularidade da escolha importam para os artigos seguintes. Se todas as prestações falharem, a solução pode ser diferente.", "Inexequível", "prestação que não pode ser realizada material ou juridicamente"),
    "254": row("Se todas as alternativas se tornam impossíveis por culpa do devedor e a escolha não cabia ao credor, ele paga o valor da prestação que por último se impossibilitou e as perdas e danos cabíveis.", "O último objeto possível fixa o equivalente principal porque era nele que a obrigação havia terminado por se concentrar. A indenização cobre prejuízos adicionais comprovados.", "Devedor destrói sucessivamente os dois bens que poderia entregar; paga o valor daquele perdido por último e indeniza o dano excedente.", "A regra pressupõe culpa do devedor e escolha não atribuída ao credor. Outros cenários seguem os arts. 255 e 256.", "Equivalente", "valor econômico que substitui a prestação impossível"),
    "255": row("Quando a escolha pertence ao credor e uma alternativa se torna impossível por culpa do devedor, ele pode exigir a restante ou o valor da perdida, com indenização. Se ambas falharem por culpa, escolhe o valor de qualquer uma, também com perdas e danos.", "A titularidade da opção amplia a proteção do credor: a conduta do devedor não pode retirar a escolha que lhe havia sido conferida.", "Credor podia escolher entre dois veículos; o devedor inutiliza um e o credor opta pelo outro ou pelo valor do destruído.", "A indenização exige prejuízo e nexo causal e não autoriza reparação duplicada. Impossibilidade sem culpa segue regime distinto.", "Titular da escolha", "pessoa a quem o contrato ou a lei atribui a opção entre as prestações"),
    "256": row("A obrigação alternativa extingue-se quando todas as prestações se tornam impossíveis sem culpa do devedor.", "Se nenhum dos objetos pode mais ser cumprido e o devedor não causou a impossibilidade, falta prestação possível e não nasce indenização baseada em culpa.", "Dois bens únicos previstos como alternativas são destruídos por evento inevitável antes da entrega; a obrigação se encerra.", "É preciso comprovar impossibilidade total, ausência de culpa e inexistência de mora relevante. Dificuldade ou maior custo não equivalem automaticamente à impossibilidade.", "Impossibilidade fortuita", "inviabilidade de cumprir causada sem culpa do devedor"),
    "257": row("Em obrigação divisível com vários credores ou devedores, presumem-se tantas obrigações iguais e independentes quantas forem as pessoas de cada lado.", "Cada credor exige sua fração e cada devedor responde pela própria parte. A divisibilidade da prestação, e não apenas a pluralidade de sujeitos, permite o fracionamento.", "Três devedores devem quantia divisível; na ausência de regra diferente, cada um responde por um terço.", "A presunção pode ceder a estipulação, lei ou circunstância aplicável. Não confunda divisão da dívida com solidariedade, que precisa de fonte própria.", "Obrigação divisível", "prestação que pode ser fracionada sem perda relevante de substância ou finalidade"),
    "258": row("A obrigação é indivisível quando a coisa ou o fato não admite fracionamento por natureza, razão econômica ou finalidade determinante do negócio.", "A indivisibilidade pode decorrer das características físicas, de perda de valor econômico com a divisão ou do objetivo concreto que levou as partes a contratar.", "A entrega de uma obra de arte única não pode ser repartida entre os devedores sem destruir a prestação.", "Indivisibilidade diz respeito ao objeto; solidariedade diz respeito ao vínculo entre sujeitos. Os institutos podem produzir efeitos semelhantes, mas não são idênticos.", "Indivisibilidade", "impossibilidade jurídica ou prática de fracionar a prestação devida"),
    "259": row("Havendo vários devedores de prestação indivisível, cada um pode ser cobrado pelo todo. Quem cumpre integralmente assume, perante os demais, o direito do credor.", "A cobrança integral é necessária porque o objeto não comporta divisão. O pagador pode recuperar dos coobrigados as parcelas internas correspondentes.", "Um dos coproprietários entrega sozinho o animal único devido e depois cobra dos demais a participação que lhes cabia.", "A responsabilidade pelo todo decorre aqui da indivisibilidade, não de solidariedade presumida. A relação interna ainda deve respeitar as quotas aplicáveis.", "Sub-rogação", "entrada de quem paga na posição jurídica do credor, nos limites legais"),
    "260": row("Quando há vários credores de prestação indivisível, qualquer um pode exigir o todo; o devedor se libera pagando a todos juntos ou a um que apresente garantia de ratificação dos demais.", "A caução protege contra nova cobrança pelos outros credores. Sem pagamento conjunto, o recebedor precisa garantir que os demais confirmarão o ato.", "Devedor entrega peça única a um cocredor que oferece garantia suficiente de aprovação dos demais.", "Pagar isoladamente a um credor sem a garantia exigida pode não liberar o devedor perante os outros. A forma da caução deve ser adequada ao risco.", "Caução de ratificação", "garantia de que os demais credores confirmarão o recebimento feito por um deles"),
    "261": row("O credor de prestação indivisível que recebe sozinho o objeto inteiro deve pagar em dinheiro aos demais as quotas que lhes pertencem.", "Como não era possível dividir a própria prestação, a divisão econômica ocorre depois do recebimento. O recebedor presta contas aos cocredores conforme a participação de cada um.", "Um herdeiro recebe bem indivisível devido ao grupo e entrega aos outros o valor correspondente às suas partes.", "A regra não torna iguais quotas que sejam diferentes por título ou lei. É necessário apurar a participação interna de cada credor.", "Quota", "fração econômica pertencente a cada participante da relação"),
    "262": row("A remissão concedida por um dos credores de obrigação indivisível não elimina o direito dos demais, mas a cobrança deve descontar a quota do remitente. O mesmo vale para transação, novação, compensação e confusão.", "Um cocredor não pode dispor da parte alheia. Os outros preservam a prestação, ajustada economicamente para excluir a parcela afetada pelo ato individual.", "Um de três credores perdoa sua quota; os outros cobram o todo indivisível com o desconto correspondente.", "Cada instituto citado tem requisitos próprios. O artigo apenas uniformiza o efeito sobre a pluralidade de credores indivisíveis.", "Remissão", "perdão da dívida concedido pelo credor"),
    "263": row("Convertida a obrigação indivisível em perdas e danos, ela passa a ser divisível. Se todos os devedores tiverem culpa, respondem em partes iguais; se apenas um for culpado, só ele responde pela indenização.", "O dinheiro indenizatório pode ser repartido, eliminando a razão da indivisibilidade. A distribuição da responsabilidade depende de quem causou o inadimplemento.", "Objeto único não é entregue e vira indenização: todos respondem igualmente se contribuíram; somente o causador responde se a culpa foi exclusiva.", "A regra específica exige apuração da culpa. Não se deve transportar automaticamente a cobrança integral própria da prestação indivisível para as perdas e danos.", "Conversão em perdas e danos", "substituição da prestação descumprida por indenização pecuniária"),
    "264": row("Existe solidariedade quando vários credores podem exigir, ou vários devedores devem cumprir, a dívida inteira dentro da mesma obrigação.", "Na solidariedade ativa, cada credor tem direito ao todo; na passiva, cada devedor responde pelo todo perante o credor. Depois do pagamento, ajustam-se as quotas internas.", "Banco pode cobrar toda a dívida de qualquer um dos devedores solidários previstos no contrato.", "Solidariedade não significa indivisibilidade: mesmo uma quantia divisível pode ser solidária. Também não se presume, conforme o artigo seguinte.", "Solidariedade", "vínculo pelo qual cada credor ou devedor se relaciona com a totalidade da dívida"),
    "265": row("A solidariedade somente existe quando decorre da lei ou de manifestação de vontade das partes; não nasce por presunção.", "Quem pretende cobrar um devedor pelo total ou reconhecer a qualquer credor direito ao todo deve demonstrar a fonte legal ou contratual do vínculo solidário.", "Dois compradores não respondem automaticamente pelo preço inteiro apenas por assinarem o mesmo negócio; é preciso fonte de solidariedade.", "Pluralidade de sujeitos, parentesco ou interesse comum não bastam por si sós. Examine a norma e a redação do título.", "Fonte da solidariedade", "lei ou cláusula negocial que cria responsabilidade ou crédito pelo total"),
    "266": row("Uma obrigação solidária pode ter condições, prazos ou lugares de pagamento diferentes para cada cocredor ou codevedor.", "A unidade da dívida não exige identidade completa das modalidades pessoais. Uma pessoa pode estar sujeita a termo ou condição que não alcança as demais.", "Um devedor solidário deve pagar imediatamente, enquanto a obrigação do outro vence em data posterior prevista no contrato.", "A diferença de modalidade não extingue a solidariedade, mas deve ser respeitada ao cobrar cada participante. Não se antecipa prazo alheio.", "Modalidade da obrigação", "condição, termo ou circunstância que altera exigibilidade ou modo de cumprir"),
    "267": row("Cada credor solidário pode exigir do devedor o cumprimento integral da prestação.", "A solidariedade ativa legitima qualquer cocredor a cobrar o todo, embora o valor recebido tenha de ser posteriormente repartido na relação interna.", "Um dos credores solidários ajuíza cobrança de toda a quantia devida ao grupo.", "O direito de exigir o todo não transforma o credor em proprietário exclusivo do resultado. Ele responde aos demais pelas respectivas partes.", "Credor solidário", "cocredor autorizado a exigir a totalidade da dívida comum"),
    "268": row("Antes que algum credor solidário demande o devedor comum, este pode escolher pagar a qualquer um deles.", "A liberdade de escolha do devedor termina quando uma cobrança judicial individualiza o credor perante quem o pagamento deve ser feito no processo.", "Sem ação em curso, o devedor quita a dívida com um dos três credores solidários.", "Depois de proposta a demanda, pagar a outro credor pode não liberar o devedor na mesma extensão. Verifique ciência e contexto processual.", "Demandar", "formular judicialmente uma pretensão contra alguém"),
    "269": row("O pagamento a um credor solidário extingue a dívida na medida exata do valor pago.", "Pagamento integral libera o devedor de toda a obrigação; pagamento parcial reduz o saldo comum, que ainda pode ser cobrado.", "Devedor paga sessenta de uma dívida de cem a um cocredor solidário; restam quarenta perante o conjunto.", "A quitação deve identificar o montante efetivamente recebido. A divisão interna entre credores não autoriza cobrar novamente do devedor o que já foi pago.", "Extinção parcial", "redução da dívida somente até o valor efetivamente satisfeito"),
    "270": row("Com a morte de credor solidário, cada herdeiro só pode exigir a parcela correspondente ao próprio quinhão, salvo se a prestação for indivisível.", "A herança fraciona a posição do falecido entre seus sucessores. Reunidos, eles representam a quota total que cabia ao credor originário.", "Credor solidário deixa dois herdeiros iguais; cada um cobra metade da posição hereditária, e não a dívida inteira.", "A exceção da indivisibilidade impede fracionar o objeto. Também é preciso distinguir a quota do falecido da participação dos demais credores solidários.", "Quinhão hereditário", "parte da herança atribuída a cada sucessor"),
    "271": row("Se a prestação solidária se converte em perdas e danos, a solidariedade ativa continua existindo.", "A substituição do objeto por indenização não divide automaticamente o crédito entre os cocredores. Cada um conserva legitimidade para exigir o total indenizatório.", "Entrega impossível vira indenização em dinheiro, que ainda pode ser cobrada integralmente por qualquer credor solidário.", "Quem recebe o total continua responsável pelas quotas internas dos outros credores. Não confunda esta regra com a perda da indivisibilidade do art. 263.", "Subsistência", "continuidade de um vínculo apesar da mudança da prestação"),
    "272": row("O credor solidário que perdoa a dívida ou recebe pagamento deve repassar aos outros as partes que lhes correspondem.", "A possibilidade de agir sozinho perante o devedor não permite apropriar-se das quotas alheias nem prejudicá-las gratuitamente na relação interna.", "Um cocredor recebe toda a dívida e deve distribuir aos demais os valores das respectivas quotas.", "A extensão da responsabilidade depende das participações internas e do ato praticado. A dívida perante o devedor e o acerto entre credores são planos distintos.", "Relação interna", "acerto de quotas entre participantes do mesmo polo da obrigação"),
    "273": row("O devedor não pode usar contra um credor solidário uma defesa pessoal que somente teria contra outro cocredor.", "Defesas ligadas à dívida comum podem ser relevantes; circunstâncias estritamente pessoais de um credor não reduzem o direito dos demais.", "Devedor tem crédito compensável apenas contra um cocredor e não o invoca para afastar cobrança feita por outro.", "É indispensável classificar a exceção como comum ou pessoal. A regra protege a autonomia das posições individuais dentro da solidariedade.", "Exceção pessoal", "defesa fundada em circunstância particular de uma pessoa, e não na dívida comum"),
    "274": row("Decisão desfavorável a um credor solidário não prejudica os outros. Decisão favorável pode beneficiá-los, preservada a defesa pessoal que o devedor possua contra qualquer deles.", "O resultado negativo não se expande automaticamente; o positivo pode aproveitar ao grupo, mas não elimina particularidades defensivas oponíveis a credor específico.", "Um cocredor perde a ação e os demais ainda podem cobrar; se vence questão comum, o benefício pode alcançá-los.", "O efeito favorável não supera exceção pessoal válida. A análise processual concreta continua necessária para definir alcance e coisa julgada.", "Julgamento favorável", "decisão que reconhece pretensão útil ao credor que demandou"),
    "275": row("O credor pode cobrar toda ou parte da dívida de um, de alguns ou de todos os devedores solidários. Pagamento parcial mantém todos vinculados pelo saldo.", "A escolha de quem cobrar pertence ao credor e a ação contra apenas alguns não significa renúncia à solidariedade.", "Credor cobra setenta de um codevedor; os demais continuam solidariamente responsáveis pelos trinta restantes.", "O credor não pode receber mais que o total. Pagamento, acordos e quitações devem ser computados no saldo comum.", "Solidariedade passiva", "responsabilidade de cada codevedor pela totalidade da dívida perante o credor"),
    "276": row("Morto um devedor solidário, cada herdeiro responde apenas na proporção do próprio quinhão, salvo indivisibilidade; reunidos, todos equivalem a um devedor solidário perante os demais codevedores.", "A sucessão limita individualmente cada herdeiro, mas preserva coletivamente a posição do falecido na dívida.", "Três herdeiros sucedem codevedor: cada um suporta sua fração; o conjunto representa a quota solidária do falecido.", "A responsabilidade sucessória também observa os limites gerais da herança. Prestação indivisível recebe tratamento específico.", "Sucessão do devedor", "transferência da posição patrimonial do falecido aos herdeiros nos limites legais"),
    "277": row("Pagamento parcial ou perdão obtido por um devedor reduz a dívida dos demais somente até o valor pago ou remitido.", "O benefício econômico ingressa no saldo comum, mas não libera os codevedores além de sua quantia.", "Credor perdoa vinte a um devedor solidário numa dívida de cem; os demais continuam responsáveis por oitenta.", "Remissão parcial não equivale necessariamente a renúncia da solidariedade. O instrumento deve ser interpretado para separar redução do saldo e exoneração pessoal.", "Concorrência da quantia", "limite correspondente ao valor efetivamente pago ou perdoado"),
    "278": row("Acordo entre o credor e apenas um devedor solidário não pode piorar a situação dos outros sem o consentimento deles.", "Cláusula, condição ou encargo adicional é pessoal aos participantes do ajuste, salvo concordância dos demais codevedores.", "Credor combina multa extra com um devedor; não pode cobrá-la dos outros que não aceitaram.", "A regra impede agravamento, não necessariamente benefício. Alterações da dívida comum e atos pessoais devem ser cuidadosamente distinguidos.", "Obrigação adicional", "novo encargo acrescentado ao vínculo original"),
    "279": row("Se a prestação se torna impossível por culpa de um devedor solidário, todos respondem pelo equivalente, mas apenas o culpado paga as perdas e danos adicionais.", "A dívida principal em valor permanece solidária; a indenização decorrente da culpa é pessoal de quem causou a impossibilidade.", "Um codevedor destrói o bem devido: qualquer devedor pode ser cobrado pelo valor, e o destruidor responde sozinho pelos prejuízos extras.", "É preciso separar equivalente e danos suplementares. Na relação interna, o culpado pode ter responsabilidade regressiva mais ampla.", "Equivalente pecuniário", "valor em dinheiro que substitui a prestação tornada impossível"),
    "280": row("Todos os devedores solidários respondem pelos juros de mora, mesmo que a ação tenha sido proposta contra apenas um; o culpado pelo acréscimo deve ressarcir os demais.", "Perante o credor, os juros integram o saldo solidário. Internamente, quem provocou a mora suporta o custo acrescido.", "A demora imputável a um codevedor gera juros cobrados de qualquer um; quem pagar cobra do causador a parcela adicional.", "Responsabilidade externa e acerto regressivo são distintos. Devem ser apurados o período da mora e a causa do acréscimo.", "Juros de mora", "acréscimo devido pelo atraso no cumprimento da obrigação"),
    "281": row("O devedor solidário cobrado pode alegar defesas próprias e defesas comuns a todos, mas não pode aproveitar defesa exclusivamente pessoal de outro codevedor.", "Circunstâncias que atingem a própria posição ou a dívida comum podem impedir ou reduzir a cobrança. Benefícios pessoais alheios permanecem restritos.", "Devedor invoca pagamento da dívida, defesa comum, mas não incapacidade particular de outro codevedor.", "Classificar corretamente a exceção é decisivo. Compensação, vícios de consentimento e benefícios pessoais dependem do caso concreto.", "Exceção comum", "defesa que atinge a própria dívida e aproveita a todos os devedores"),
    "282": row("O credor pode abrir mão da solidariedade em favor de um, de alguns ou de todos os devedores. Se beneficiar apenas parte deles, a solidariedade continua entre os restantes.", "Renunciar à solidariedade não significa necessariamente perdoar a dívida: o beneficiado continua devendo sua quota, salvo remissão adicional.", "Credor retira um codevedor do vínculo pelo total; ele conserva obrigação por sua parte, e os demais seguem solidários.", "Diferencie exoneração da solidariedade e extinção da dívida. A declaração do credor e seus limites precisam ser claros.", "Renúncia à solidariedade", "ato pelo qual o credor deixa de cobrar de certo devedor além da quota dele"),
    "283": row("Quem paga integralmente a dívida solidária pode cobrar de cada codevedor sua quota. A parte do insolvente é repartida igualmente entre os demais, presumindo-se iguais as participações.", "O pagamento extingue a relação com o credor e abre o regresso interno. Se alguém não puder pagar, sua quota é redistribuída entre os participantes responsáveis.", "Um de três codevedores quita tudo; cobra um terço de cada, repartindo a quota de eventual insolvente conforme a regra.", "A igualdade é presunção e pode ceder a prova de quotas diferentes ou interesse exclusivo tratado no art. 285.", "Direito de regresso", "direito de quem pagou cobrar dos coobrigados as partes internas deles"),
    "284": row("No rateio da quota do codevedor insolvente, também participam aqueles que o credor havia liberado da solidariedade.", "A exoneração produz efeito perante o credor, mas não elimina a contribuição interna do beneficiado para repartir a insolvência de outro participante.", "Um codevedor exonerado do vínculo pelo total ainda contribui no rateio da parte que terceiro insolvente não paga.", "A contribuição limita-se à parcela interna aplicável. Não se restaura, por esse motivo, a solidariedade externa já renunciada.", "Rateio", "distribuição proporcional ou igualitária de uma parcela entre os responsáveis"),
    "285": row("Se a dívida solidária beneficia exclusivamente um devedor, ele deve reembolsar integralmente o codevedor que a pagar.", "Embora o credor pudesse cobrar qualquer responsável, na relação interna o único interessado econômico suporta todo o débito.", "Sócio garante solidariamente dívida usada apenas por outro; se o garantidor paga, cobra dele o valor completo.", "O interesse exclusivo precisa ser demonstrado. Se o benefício foi compartilhado, aplicam-se as quotas internas correspondentes.", "Interesse exclusivo", "benefício econômico da dívida concentrado em apenas um dos devedores"),
    "286": row("O credor pode transferir seu crédito, salvo impedimento pela natureza da obrigação, pela lei ou por pacto com o devedor. Proibição contratual só atinge cessionário de boa-fé se constar do instrumento da obrigação.", "A cessão muda o titular do crédito sem substituir o devedor. Créditos personalíssimos ou legalmente intransferíveis não circulam.", "Fornecedor cede recebível a banco, que passa a cobrá-lo do comprador.", "Verifique limitações legais e contratuais. A boa-fé do cessionário e a presença da cláusula proibitiva no documento original são relevantes.", "Cessionário", "pessoa que recebe o crédito transferido pelo credor anterior"),
    "287": row("Salvo acordo diferente, a cessão de crédito transfere também os acessórios ligados a ele.", "Garantias, juros e outros elementos dependentes acompanham o crédito principal para preservar sua utilidade, dentro dos limites do título e da lei.", "Crédito garantido por fiança é cedido juntamente com os acessórios aplicáveis, se nada foi excluído.", "Nem todo direito relacionado é necessariamente acessório transferível. Examine a natureza da garantia, eventual consentimento e cláusulas específicas.", "Acessório do crédito", "direito ou garantia dependente do crédito principal"),
    "288": row("A cessão só produz efeitos perante terceiros se formalizada por instrumento público ou por instrumento particular com as solenidades legais referidas.", "Entre cedente e cessionário pode haver vínculo, mas a oponibilidade externa exige forma documental qualificada, que assegure identificação e autenticidade.", "Duas pessoas disputam o mesmo crédito; a cessão sem forma adequada pode ser ineficaz perante a terceira interessada.", "Ineficácia perante terceiros não equivale automaticamente a nulidade entre as partes. A forma e o conflito concreto devem ser examinados.", "Oponibilidade", "possibilidade de fazer um ato produzir efeitos contra terceiros"),
    "289": row("Quem recebe por cessão um crédito hipotecário pode averbar a transferência no registro do imóvel.", "A averbação atualiza a publicidade registral da titularidade do crédito garantido pela hipoteca e protege a circulação segura do direito.", "Banco adquire crédito hipotecário e registra a cessão na matrícula do imóvel dado em garantia.", "A cessão do crédito não transfere a propriedade do imóvel. Devem ser cumpridos os requisitos do registro imobiliário.", "Averbação", "anotação registral que atualiza informação jurídica vinculada a um registro existente"),
    "290": row("A cessão só é eficaz contra o devedor depois de notificada, salvo se ele declarar por escrito que já sabe da transferência.", "A ciência indica a quem o pagamento deve ser feito. Antes dela, o devedor ainda pode legitimamente tratar com o credor original nas condições legais.", "Empresa recebe notificação de que a fatura foi cedida e passa a pagar ao novo credor.", "A notificação não é requisito geral de existência da cessão entre cedente e cessionário; sua função central é torná-la oponível ao devedor.", "Notificação da cessão", "comunicação formal ao devedor de que o crédito mudou de titular"),
    "291": row("Se o mesmo crédito é cedido várias vezes, prevalece a cessão completada pela entrega do título representativo do crédito.", "A tradição do documento resolve o conflito entre cessionários quando a circulação depende do título, privilegiando quem obteve sua posse nos termos legais.", "Credor cede o mesmo título a duas pessoas; prevalece quem recebe efetivamente o documento do crédito.", "A regra pressupõe título suscetível de tradição. Créditos em escritura pública e notificações recebem disciplina complementar no artigo seguinte.", "Tradição do título", "entrega do documento que representa o crédito cedido"),
    "292": row("Paga validamente quem, sem conhecer a cessão, paga ao credor antigo. Havendo várias cessões notificadas, libera-se pagando ao cessionário que apresenta os títulos pertinentes; em escritura pública, prevalece a notificação anterior.", "A norma protege a boa-fé do devedor e fornece critério para escolher o credor correto em cessões concorrentes.", "Devedor não avisado paga ao cedente original e não precisa pagar novamente.", "Conhecimento efetivo, notificações e documentos apresentados devem ser provados. Depois da ciência, pagamento ao credor antigo pode não liberar.", "Credor primitivo", "titular original do crédito antes da cessão"),
    "293": row("O cessionário pode adotar medidas para conservar o crédito mesmo antes de o devedor conhecer a cessão.", "A falta de notificação impede eficácia contra o devedor, mas não obriga o novo titular a assistir passivamente à perda ou deterioração de seu direito.", "Cessionário pede medida para impedir prescrição ou dissipação de garantia antes de concluir a notificação.", "Atos conservatórios preservam o crédito; não significam que toda cobrança ou recebimento contra o devedor já seja eficaz sem ciência.", "Ato conservatório", "providência destinada a impedir perda ou enfraquecimento de um direito"),
    "294": row("O devedor pode opor ao cessionário suas defesas próprias e aquelas que tinha contra o cedente quando tomou conhecimento da cessão.", "A transferência não pode piorar retroativamente a posição do devedor. Defesas já existentes permanecem, mas fatos pessoais surgidos depois contra o antigo credor não atingem necessariamente o cessionário.", "Devedor já possuía crédito compensável contra o cedente ao ser notificado e o apresenta ao novo credor.", "O momento da ciência é decisivo para defesas contra o cedente. Devem ser separadas exceções do próprio crédito e relações posteriores.", "Cedente", "credor que transfere seu crédito a outra pessoa"),
    "295": row("Na cessão onerosa, o cedente responde pela existência do crédito no momento da transferência, mesmo sem cláusula de garantia. Na gratuita, responde se agiu de má-fé.", "Quem vende crédito garante que ele existe; quem o doa só responde pela inexistência quando conhecia o problema e procedeu deslealmente.", "Pessoa vende crédito já inexistente e deve responder ao comprador, ainda que não tenha garantido o pagamento pelo devedor.", "Existência do crédito não se confunde com solvência do devedor, disciplinada separadamente. O momento relevante é o da cessão.", "Cessão onerosa", "transferência do crédito mediante contraprestação"),
    "296": row("Em regra, quem cede o crédito não garante que o devedor terá patrimônio para pagá-lo; essa responsabilidade depende de estipulação.", "O cessionário assume normalmente o risco de insolvência, embora continue protegido quanto à existência do crédito conforme o artigo anterior.", "Investidor compra crédito válido, mas o devedor fica insolvente; o cedente não responde sem cláusula específica.", "A ausência de garantia de solvência não protege fraude, inexistência do crédito ou outras responsabilidades legais. Leia o contrato da cessão.", "Solvência", "capacidade patrimonial de satisfazer as próprias dívidas"),
    "297": row("Quando o cedente assume responsabilidade pela solvência, seu dever limita-se ao que recebeu, com juros, mais despesas da cessão e da cobrança realizadas pelo cessionário.", "A garantia não transforma o cedente automaticamente em devedor integral do valor nominal do crédito; a lei delimita a recomposição devida.", "Cedente recebeu oitenta pela cessão de crédito de cem e, acionada a garantia, restitui o recebido com os acréscimos e despesas legais.", "É preciso demonstrar a garantia, a insolvência e as despesas. Cláusulas válidas podem disciplinar a responsabilidade dentro dos limites aplicáveis.", "Responsabilidade pela solvência", "garantia excepcional de que o devedor terá condições de pagar"),
    "298": row("Depois de saber que o crédito foi penhorado, o credor não pode transferi-lo. Se o devedor paga sem ter sido notificado da penhora, fica liberado, e o terceiro prejudicado age contra o credor.", "A constrição retira do titular a livre disponibilidade do crédito, mas a boa-fé do devedor não avisado é preservada.", "Credor cede recebível já penhorado apesar de conhecer a medida; devedor não notificado paga e não deve novamente.", "Conhecimento do credor e notificação do devedor são fatos distintos e relevantes. A penhora também segue regras processuais próprias.", "Penhora de crédito", "apreensão judicial do direito de receber para garantir uma execução"),
    "299": row("Terceiro pode assumir a dívida com consentimento expresso do credor, liberando o devedor original, salvo insolvência anterior do substituto ignorada pelo credor. O silêncio do credor, após prazo fixado, vale como recusa.", "A assunção troca o sujeito devedor e exige concordância clara de quem receberá. A proteção contra insolvência oculta evita liberação baseada em risco desconhecido.", "Comprador assume dívida do vendedor e o banco concorda expressamente com a substituição.", "Não presuma consentimento do silêncio. Diferencie assunção liberatória de mera promessa interna de pagar dívida alheia.", "Assunção de dívida", "negócio pelo qual terceiro passa a ocupar a posição de devedor"),
    "300": row("Com a assunção da dívida, garantias especiais fornecidas pelo devedor original se extinguem, salvo consentimento expresso dele para mantê-las.", "A liberação do devedor também retira garantias que ele próprio havia constituído; preservá-las exige concordância específica.", "Devedor hipotecou bem próprio e depois é substituído; a garantia deixa de valer se ele não autorizar expressamente sua continuidade.", "A regra trata das garantias dadas pelo devedor primitivo. Garantias de terceiros e restauração por anulação recebem disciplina própria.", "Garantia especial", "segurança específica acrescida ao crédito, como penhor ou hipoteca"),
    "301": row("Anulada a substituição do devedor, a dívida e suas garantias são restauradas. Garantias de terceiros não retornam, salvo se o garantidor conhecia o vício da assunção.", "A invalidação procura recompor a obrigação anterior, mas protege terceiro garantidor de boa-fé que havia sido liberado.", "Assunção é anulada e volta a dívida original; fiança de terceiro só revive se o fiador conhecia o defeito.", "O artigo pressupõe anulação da substituição, não simples inadimplemento do novo devedor. Conhecimento do vício deve ser demonstrado.", "Restauração do débito", "retorno da obrigação anterior após a invalidação da substituição"),
    "302": row("O novo devedor não pode apresentar ao credor defesas estritamente pessoais que pertenciam ao devedor anterior.", "A assunção transfere a dívida, mas não benefícios defensivos vinculados às características ou relações particulares do sujeito substituído.", "Novo devedor não invoca crédito pessoal que o devedor antigo possuía contra o credor.", "Defesas comuns à própria dívida podem continuar relevantes. É necessário distinguir vício objetivo do débito e exceção pessoal do substituído.", "Exceção pessoal", "defesa ligada exclusivamente à pessoa ou relação particular do antigo devedor"),
    "303": row("O comprador de imóvel hipotecado pode assumir a dívida garantida. Notificado, o credor que não se opõe em trinta dias é considerado concordante.", "Esta hipótese especial admite consentimento tácito pelo silêncio qualificado, diferentemente da regra geral do art. 299.", "Comprador assume financiamento hipotecário; o banco recebe notificação e não impugna dentro de trinta dias.", "É indispensável notificação apta a iniciar o prazo. A assunção do débito não elimina automaticamente a hipoteca que o garante.", "Imóvel hipotecado", "bem gravado como garantia real de determinado crédito"),
    "304": row("Qualquer pessoa com interesse jurídico na extinção da dívida pode pagá-la e, diante de oposição do credor, usar meios para liberar o devedor. Terceiro sem interesse também pode pagar em nome e por conta do devedor, salvo oposição deste.", "O ordenamento favorece o adimplemento, mas distingue interessado e simples terceiro quanto a efeitos posteriores.", "Fiador paga a dívida garantida para evitar sua própria responsabilização.", "Quem paga, em qual nome e com ou sem oposição do devedor influencia reembolso e sub-rogação nos artigos seguintes.", "Terceiro interessado", "pessoa que pode sofrer consequência jurídica se a dívida não for paga"),
    "305": row("Terceiro sem interesse que paga em nome próprio pode pedir reembolso, mas não assume os direitos e garantias do credor. Se antecipa dívida, só cobra no vencimento.", "O pagamento cria pretensão de restituição contra o devedor, sem sub-rogação legal. A antecipação voluntária não antecipa a exigibilidade do reembolso.", "Amigo paga dívida alheia em seu próprio nome e depois cobra apenas o que desembolsou na data devida.", "A regra difere do pagamento feito por interessado e do pagamento em nome do devedor. Garantias do crédito original não acompanham automaticamente o terceiro.", "Reembolso", "restituição ao terceiro do valor que desembolsou por outra pessoa"),
    "306": row("Pagamento feito sem conhecimento ou contra a vontade do devedor não gera reembolso se o devedor tinha defesa capaz de impedir a cobrança.", "Ninguém deve impor ao devedor o custo de uma dívida que ele poderia validamente afastar. O terceiro assume o risco de pagar sem consultar ou apesar da oposição.", "Terceiro paga obrigação já prescrita contra a oposição do devedor que podia impedir a ação e não obtém reembolso.", "O devedor deve demonstrar meio eficaz de ilidir a cobrança. A regra não elimina automaticamente todo reembolso por falta de ciência.", "Ilidir a ação", "afastar juridicamente a pretensão de cobrança mediante defesa eficaz"),
    "307": row("Pagamento que transfere propriedade só é eficaz se realizado por quem podia alienar o objeto. Porém, coisa fungível recebida e consumida de boa-fé pelo credor não pode ser reclamada dele.", "O pagamento com bem exige poder de disposição. A exceção protege a segurança de quem consumiu bem substituível sem conhecer o defeito.", "Pessoa entrega dinheiro alheio que o credor recebe e gasta de boa-fé; não se exige dele a restituição daquela mesma coisa.", "A proteção depende de fungibilidade, boa-fé e consumo. Direitos contra quem pagou indevidamente podem permanecer.", "Poder de alienar", "legitimidade jurídica para transferir a propriedade de um bem"),
    "308": row("O pagamento deve ser feito ao credor ou representante legítimo. Se entregue a outra pessoa, só vale quando ratificado pelo credor ou na medida em que efetivamente o beneficia.", "O devedor deve conferir legitimidade de quem recebe. A confirmação posterior ou o proveito demonstrado pode validar total ou parcialmente o pagamento irregular.", "Devedor paga a funcionário sem poderes; o credor depois confirma o recebimento e valida o ato.", "O ônus de demonstrar ratificação ou benefício recai sobre quem invoca o pagamento. Aparência de legitimidade pode envolver o art. 309.", "Ratificação", "confirmação posterior que torna eficaz ato antes praticado sem autorização suficiente"),
    "309": row("É válido o pagamento feito de boa-fé a quem aparentava ser credor, mesmo que depois se prove que não era.", "A lei protege o devedor que, diante de circunstâncias objetivas, acreditou legitimamente estar pagando à pessoa correta.", "Cessionário aparente apresenta documentação plausível e recebe; posteriormente descobre-se defeito desconhecido pelo devedor.", "Boa-fé subjetiva deve vir acompanhada de aparência justificável. Negligência grave ou ciência do defeito afasta a proteção.", "Credor putativo", "pessoa que aparenta legitimamente ser credora, embora juridicamente não seja"),
    "310": row("Pagamento conscientemente feito a credor incapaz de dar quitação não vale, salvo prova de que o valor ou bem efetivamente reverteu em benefício dele.", "Quem sabe da incapacidade assume o dever de demonstrar utilidade concreta do pagamento para o incapaz; sem essa prova, pode permanecer obrigado.", "Devedor entrega dinheiro diretamente a incapaz e prova que a quantia foi usada integralmente em tratamento necessário dele.", "Não basta alegar entrega material. Devem ser demonstrados conhecimento da incapacidade, aptidão para quitar e extensão do benefício efetivo.", "Capacidade de quitar", "aptidão jurídica para receber pagamento e liberar validamente o devedor"),
}
